B.OM=new A.ad("NEW MIN HEAP","YEN\u0130 M\u0130N \xd6NCEL\u0130K KUYRU\u011eU","A new, empty heap that always has its smallest number on top.","Yeni ve bo\u015f bir \xf6ncelik kuyru\u011fu; en k\xfc\xe7\xfck say\u0131 hep tepededir.","SET waiting TO NEW MIN HEAP",null)
B.Q3=new A.ad("NEW MAX HEAP","YEN\u0130 MAKS \xd6NCEL\u0130K KUYRU\u011eU","A new, empty heap that always has its largest number on top.","Yeni ve bo\u015f bir \xf6ncelik kuyru\u011fu; en b\xfcy\xfck say\u0131 hep tepededir.","SET best TO NEW MAX HEAP",null)
B.Pu=new A.ad("INSERT","\xd6NCEL\u0130K KUYRU\u011eUNA EKLE","Puts a number into a heap. The heap keeps its smallest (or largest) number on top, whatever order they come in.","\xd6ncelik kuyru\u011funa bir say\u0131 ekler. Say\u0131lar hangi s\u0131rayla gelirse gelsin, en k\xfc\xe7\xfck (ya da en b\xfcy\xfck) say\u0131 tepede kal\u0131r.","INSERT waiting cost",null)
B.PG=new A.ad("TAKE TOP","TEPEDEK\u0130N\u0130 AL","Takes the top number out of a heap and gives it: the smallest for a MIN heap, the largest for a MAX heap. An empty heap is an error: check IS EMPTY first.","Tepedeki say\u0131y\u0131 \xf6ncelik kuyru\u011fundan \xe7\u0131kar\u0131r ve verir: MIN i\xe7in en k\xfc\xe7\xfc\u011f\xfc, MAX i\xe7in en b\xfcy\xfc\u011f\xfc. Bo\u015f \xf6ncelik kuyru\u011fu hatad\u0131r: \xf6nce IS EMPTY ile kontrol et.","SET cheapest TO (waiting TAKE TOP)",null)
B.OV=new A.ad("TOP","TEPEYE BAK","The top number of a heap, without taking it out.","\xd6ncelik kuyru\u011funun tepesindeki say\u0131; \xe7\u0131karmadan bakar.","IF (best TOP) LESS THAN x",null)
B.Q9=new A.ad("SIZE (heap)","\xd6NCEL\u0130K KUYRU\u011eU BOYUTU","How many numbers a heap holds.","\xd6ncelik kuyru\u011funun ka\xe7 say\u0131 tuttu\u011fu.","IF (best SIZE) GREATER THAN k",null)
B.P8=new A.ad("IS EMPTY (heap)","\xd6NCEL\u0130K KUYRU\u011eU BO\u015e MU","TRUE when the heap holds nothing.","\xd6ncelik kuyru\u011fu hi\xe7bir \u015fey tutmuyorsa TRUE olur.","WHILE NOT (waiting IS EMPTY)",null)
B.P4=new A.ad("NODE VALUE (chain)","HALKA DE\u011eER\u0130","The number written on a link of a chain (linked list).","Bir zincirin (ba\u011fl\u0131 liste) halkas\u0131n\u0131n \xfczerindeki say\u0131.","SET total TO total PLUS (node NODE VALUE)",null)
B.OP=new A.ad("NEXT NODE","SONRAK\u0130 HALKA","The link after this one, or NOTHING at the end of the chain.","Bu halkadan sonraki halka; zincirin sonunda NOTHING.","SET node TO (node NEXT NODE)",null)
B.Py=new A.ad("SET NEXT","SONRAK\u0130N\u0130 BA\u011eLA","Makes a link point to another link (or NOTHING): the chain is recoupled, nothing is copied. Slots: the link, the link it should point to.","Bir halkay\u0131 ba\u015fka bir halkay\u0131 (ya da NOTHING) g\xf6sterecek \u015fekilde ba\u011flar: zincir yeniden ba\u011flan\u0131r, hi\xe7bir \u015fey kopyalanmaz. Yuvalar: halka, g\xf6sterece\u011fi halka.","SET NEXT node prev",null)
B.Pr=new A.ad("NODE VALUE (tree)","D\xdc\u011e\xdcM DE\u011eER\u0130","The number written on a node of a tree.","Bir a\u011fac\u0131n d\xfc\u011f\xfcm\xfcn\xfcn \xfczerindeki say\u0131.","IF (node NODE VALUE) GREATER THAN prev",null)
B.Q6=new A.ad("LEFT","SOL \xc7OCUK","The left child of a tree node, or NOTHING if it has none.","Bir a\u011fa\xe7 d\xfc\u011f\xfcm\xfcn\xfcn sol \xe7ocu\u011fu; yoksa NOTHING.","SET child TO (node LEFT)",null)
B.Pm=new A.ad("RIGHT","SA\u011e \xc7OCUK","The right child of a tree node, or NOTHING if it has none.","Bir a\u011fa\xe7 d\xfc\u011f\xfcm\xfcn\xfcn sa\u011f \xe7ocu\u011fu; yoksa NOTHING.","SET child TO (node RIGHT)",null)
B.Pn=new A.ad("NEIGHBORS","KOM\u015eULAR","The list of nodes you can go to from a node of a graph, in one step.","Bir \xe7izgede bir d\xfc\u011f\xfcmden tek ad\u0131mda gidilebilen d\xfc\u011f\xfcmlerin listesi.","FOR EACH next IN (metro NEIGHBORS here)",null)
B.Pb=new A.ad("MARK","\u0130\u015eARETLE","Marks a node of a graph as visited, so a search does not come back to it.","Bir \xe7izge d\xfc\u011f\xfcm\xfcn\xfc ziyaret edilmi\u015f olarak i\u015faretler; b\xf6ylece arama ona geri d\xf6nmez.","MARK islands s",null)
B.PY=new A.ad("VISITED","Z\u0130YARET ED\u0130LD\u0130 M\u0130","TRUE when a node of the graph has been marked.","\xc7izgenin bir d\xfc\u011f\xfcm\xfc i\u015faretlenmi\u015fse TRUE olur.","IF NOT (islands VISITED next)",null)
B.Pw=new A.ad("NODE COUNT","D\xdc\u011e\xdcM SAYISI","How many nodes a graph has; they are numbered 0 to (NODE COUNT) MINUS 1.","\xc7izgenin ka\xe7 d\xfc\u011f\xfcm\xfc oldu\u011fu; d\xfc\u011f\xfcmler 0'dan (NODE COUNT) MINUS 1'e kadar numaral\u0131d\u0131r.","FOR s FROM 0 TO (islands NODE COUNT) BY 1",null)
